mapper.select:
        select
        evaluate.*,
        orders.order_no,
        beautyProjects.title,
        user.nick_name,
        user.avatar
        from evaluate evaluate
        left join orders orders on evaluate.order_id = orders.id
		left join beauty_projects beautyProjects on evaluate.project_id = beautyProjects.id
		left join user user on evaluate.user_id = user.id

            and evaluate.id = #{id}
            and evaluate.order_id = #{orderId}
            and evaluate.project_id = #{projectId}
            and evaluate.user_id = #{userId}
            and evaluate.content = #{content}
            and evaluate.create_time = #{createTime}
            and orders.order_no like concat('%',#{orderNo},'%')
            and beautyProjects.title like concat('%',#{title},'%')
            and user.nick_name like concat('%',#{nickName},'%')
            and user.avatar = #{avatar}


            limit #{current},#{pageSize}

        select count(*) from evaluate evaluate
        left join orders orders on evaluate.order_id = orders.id
		left join beauty_projects beautyProjects on evaluate.project_id = beautyProjects.id
		left join user user on evaluate.user_id = user.id

            and evaluate.id = #{id}
            and evaluate.order_id = #{orderId}
            and evaluate.project_id = #{projectId}
            and evaluate.user_id = #{userId}
            and evaluate.content = #{content}
            and evaluate.create_time = #{createTime}
            and orders.order_no like concat('%',#{orderNo},'%')
            and beautyProjects.title like concat('%',#{title},'%')
            and user.nick_name like concat('%',#{nickName},'%')
            and user.avatar = #{avatar}
